// FewGaze project page. Every number shown comes from data/results.json, generated by
// scripts/generate_report_assets.py from the recorded experiment outputs.
(function () {
  "use strict";

  const SERIES_VAR = {
    geometry: "--s-geometry", dinov2: "--s-dinov2", l2cs: "--s-l2cs", clip: "--s-clip",
    geometry_linear: "--s-ablation1", dinov2_patchmean: "--s-ablation2", l2cs_embed: "--s-ablation3", clip_probe: "--s-ablation4",
  };
  const css = (v) => getComputedStyle(document.documentElement).getPropertyValue(v).trim();
  const colorOf = (m, fam) => css(SERIES_VAR[m] || SERIES_VAR[fam] || "--ink-2");
  const NS = "http://www.w3.org/2000/svg";
  const el = (tag, attrs = {}, parent) => {
    const e = document.createElementNS(NS, tag);
    for (const [k, v] of Object.entries(attrs)) e.setAttribute(k, v);
    if (parent) parent.appendChild(e);
    return e;
  };
  const f3 = (x) => (x == null || Number.isNaN(x) ? "–" : Number(x).toFixed(3));
  const budgetLabel = (b) => (b === "all" ? "ALL" : b);

  // ---------------- theme toggle ----------------
  const themeBtn = document.getElementById("theme-btn");
  const stored = (() => { try { return localStorage.getItem("fewgaze-theme"); } catch (e) { return null; } })();
  if (stored) document.documentElement.setAttribute("data-theme", stored);
  themeBtn.addEventListener("click", () => {
    const dark = document.documentElement.getAttribute("data-theme") === "dark" ||
      (!document.documentElement.getAttribute("data-theme") && matchMedia("(prefers-color-scheme: dark)").matches);
    const next = dark ? "light" : "dark";
    document.documentElement.setAttribute("data-theme", next);
    try { localStorage.setItem("fewgaze-theme", next); } catch (e) { /* storage unavailable */ }
    if (window.__fewgazeData) renderAll(window.__fewgazeData);
  });

  // ---------------- optional links: show only if the artefact exists ----------------
  const cfg = window.FEWGAZE_CONFIG || {};
  async function exists(url) {
    try { const r = await fetch(url, { method: "HEAD" }); return r.ok; } catch (e) { return false; }
  }
  (async () => {
    const paper = document.getElementById("link-paper");
    if (cfg.paperUrl && (cfg.paperUrl.startsWith("http") || (await exists(cfg.paperUrl)))) { paper.href = cfg.paperUrl; paper.hidden = false; }
    const code = document.getElementById("link-code");
    if (cfg.repoUrl) { code.href = cfg.repoUrl; code.hidden = false; document.querySelectorAll("[data-repo]").forEach((a) => { a.href = cfg.repoUrl; a.hidden = false; }); }
  })();

  // ---------------- tooltip ----------------
  function tooltip(container) {
    let t = container.querySelector(".tooltip");
    if (!t) { t = document.createElement("div"); t.className = "tooltip"; t.setAttribute("role", "status"); container.appendChild(t); }
    return {
      show(html, x, y) { t.innerHTML = html; t.style.left = x + "px"; t.style.top = y + "px"; t.classList.add("on"); },
      hide() { t.classList.remove("on"); },
    };
  }

  // ---------------- learning curve ----------------
  function learningCurve(container, data, metric, methods) {
    container.innerHTML = "";
    const curves = data.curves.filter((r) => r.metric === metric && r.condition === "clean");
    const budgets = data.protocol.budgets;
    const W = 720, H = 380, m = { l: 48, r: 18, t: 14, b: 44 };
    const svg = el("svg", { viewBox: `0 0 ${W} ${H}`, role: "img", "aria-label": `${metric} learning curves` }, container);
    const numeric = budgets.filter((b) => b !== "all").map(Number);
    const lx = (v) => Math.log(v);
    const x0 = lx(numeric[0]), x1 = lx(numeric[numeric.length - 1]);
    const plotW = W - m.l - m.r;
    const mainW = plotW * 0.84;
    const xAll = m.l + plotW - 10;
    const X = (b) => (b === "all" ? xAll : m.l + ((lx(Number(b)) - x0) / (x1 - x0)) * mainW);
    const vals = curves.flatMap((r) => [r.ci_low, r.ci_high]).filter((v) => v != null);
    let ymin = Math.min(0.5, ...vals), ymax = Math.max(...vals, 0.6);
    ymin = Math.floor(ymin * 20) / 20; ymax = Math.min(1, Math.ceil(ymax * 20) / 20);
    const Y = (v) => m.t + (1 - (v - ymin) / (ymax - ymin)) * (H - m.t - m.b);
    const grid = el("g", { class: "grid" }, svg);
    for (let v = ymin; v <= ymax + 1e-9; v += 0.05) {
      el("line", { x1: m.l, x2: W - m.r, y1: Y(v), y2: Y(v) }, grid);
      const t = el("text", { x: m.l - 8, y: Y(v) + 4, "text-anchor": "end" }, svg); t.textContent = v.toFixed(2);
    }
    el("line", { class: "chance", x1: m.l, x2: W - m.r, y1: Y(0.5), y2: Y(0.5) }, svg);
    // gap band between the last numeric budget and ALL: no measurement lies there
    el("rect", { x: m.l + mainW + 12, y: m.t, width: xAll - (m.l + mainW) - 28, height: H - m.t - m.b, fill: css("--rule-soft"), opacity: 0.6 }, svg);
    budgets.forEach((b) => { const t = el("text", { x: X(b), y: H - m.b + 18, "text-anchor": "middle" }, svg); t.textContent = budgetLabel(b); });
    const xl = el("text", { x: m.l + plotW / 2, y: H - 6, "text-anchor": "middle" }, svg);
    xl.textContent = "labelled training examples per class (log scale)";
    const tip = tooltip(container);
    const hits = [];
    methods.forEach((meth) => {
      const info = data.methods[meth];
      const c = colorOf(meth, info.family);
      const rows = curves.filter((r) => r.method === meth);
      if (!rows.length) return;
      if (info.kind === "zeroshot") {
        const r = rows[0];
        el("rect", { x: m.l, width: plotW, y: Y(r.ci_high), height: Math.max(1, Y(r.ci_low) - Y(r.ci_high)), fill: c, opacity: 0.1 }, svg);
        el("line", { x1: m.l, x2: W - m.r, y1: Y(r.estimate), y2: Y(r.estimate), stroke: c, "stroke-width": 2, "stroke-dasharray": "6 4" }, svg);
        hits.push({ x: m.l + 30, y: Y(r.estimate), r, meth, zs: true });
        return;
      }
      const num = rows.filter((r) => r.budget !== "all").sort((a, b) => Number(a.budget) - Number(b.budget));
      const band = num.map((r) => `${X(r.budget)},${Y(r.ci_high)}`).concat(num.slice().reverse().map((r) => `${X(r.budget)},${Y(r.ci_low)}`));
      el("polygon", { points: band.join(" "), fill: c, opacity: 0.14 }, svg);
      el("polyline", { points: num.map((r) => `${X(r.budget)},${Y(r.estimate)}`).join(" "), fill: "none", stroke: c, "stroke-width": 2 }, svg);
      rows.forEach((r) => {
        if (r.budget === "all") el("line", { x1: X("all"), x2: X("all"), y1: Y(r.ci_low), y2: Y(r.ci_high), stroke: c, "stroke-width": 2 }, svg);
        el("circle", { cx: X(r.budget), cy: Y(r.estimate), r: 4.5, fill: c, stroke: css("--surface"), "stroke-width": 2 }, svg);
        hits.push({ x: X(r.budget), y: Y(r.estimate), r, meth });
      });
    });
    const layer = el("rect", { x: m.l, y: m.t, width: plotW, height: H - m.t - m.b, fill: "transparent" }, svg);
    layer.addEventListener("mousemove", (ev) => {
      const pt = svg.createSVGPoint(); pt.x = ev.clientX; pt.y = ev.clientY;
      const p = pt.matrixTransform(svg.getScreenCTM().inverse());
      let best = null, bd = 1e9;
      hits.forEach((h) => { const d = h.zs ? Math.abs(h.y - p.y) * 2 : Math.hypot(h.x - p.x, h.y - p.y); if (d < bd) { bd = d; best = h; } });
      if (!best || bd > 40) return tip.hide();
      const r = best.r, rect = svg.getBoundingClientRect(), s = rect.width / W;
      const train = best.zs ? "no training labels" : `k = ${budgetLabel(r.budget)} per class · n<sub>train</sub> ≈ ${Math.round(r.mean_n_train)}`;
      tip.show(`<b>${data.methods[best.meth].label}</b><br>${train}<br>${metric === "auroc" ? "AUROC" : "Balanced acc."} ${f3(r.estimate)} <span style="opacity:.75">[${f3(r.ci_low)}, ${f3(r.ci_high)}]</span>`,
        (best.zs ? p.x : best.x) * s, best.y * s);
    });
    layer.addEventListener("mouseleave", () => tip.hide());
    return svg;
  }

  function legend(container, data, methods) {
    container.innerHTML = "";
    methods.forEach((m) => {
      const info = data.methods[m];
      const s = document.createElement("span");
      s.innerHTML = `<i class="${info.kind === "zeroshot" ? "dash" : ""}" style="border-color:${colorOf(m, info.family)}"></i>${info.label}`;
      container.appendChild(s);
    });
  }

  // ---------------- noise ----------------
  function noiseChart(container, data, budget, methods) {
    container.innerHTML = "";
    const W = 340, H = 240, m = { l: 40, r: 10, t: 22, b: 36 };
    const svg = el("svg", { viewBox: `0 0 ${W} ${H}`, role: "img", "aria-label": `label noise at k=${budget}` }, container);
    const rows = data.curves.filter((r) => r.metric === "auroc" && r.budget === budget && (r.condition === "noise" || r.condition === "clean"));
    const vals = rows.filter((r) => methods.includes(r.method)).flatMap((r) => [r.ci_low, r.ci_high]);
    let ymin = Math.floor(Math.min(0.5, ...vals) * 10) / 10, ymax = Math.min(1, Math.ceil(Math.max(...vals) * 10) / 10);
    const X = (v) => m.l + (v / 0.3) * (W - m.l - m.r);
    const Y = (v) => m.t + (1 - (v - ymin) / (ymax - ymin)) * (H - m.t - m.b);
    const g = el("g", { class: "grid" }, svg);
    for (let v = ymin; v <= ymax + 1e-9; v += 0.1) {
      el("line", { x1: m.l, x2: W - m.r, y1: Y(v), y2: Y(v) }, g);
      el("text", { x: m.l - 6, y: Y(v) + 4, "text-anchor": "end" }, svg).textContent = v.toFixed(1);
    }
    [0, 0.1, 0.2, 0.3].forEach((v) => { el("text", { x: X(v), y: H - m.b + 16, "text-anchor": "middle" }, svg).textContent = `${Math.round(v * 100)}%`; });
    el("text", { x: m.l, y: 12 }, svg).textContent = `k = ${budget} per class`;
    el("line", { class: "chance", x1: m.l, x2: W - m.r, y1: Y(0.5), y2: Y(0.5) }, svg);
    const tip = tooltip(container);
    methods.forEach((meth) => {
      const q = rows.filter((r) => r.method === meth).sort((a, b) => a.noise_rate - b.noise_rate);
      if (q.length < 2) return;
      const c = colorOf(meth, data.methods[meth].family);
      el("polygon", { points: q.map((r) => `${X(r.noise_rate)},${Y(r.ci_high)}`).concat(q.slice().reverse().map((r) => `${X(r.noise_rate)},${Y(r.ci_low)}`)).join(" "), fill: c, opacity: 0.12 }, svg);
      el("polyline", { points: q.map((r) => `${X(r.noise_rate)},${Y(r.estimate)}`).join(" "), fill: "none", stroke: c, "stroke-width": 2 }, svg);
      q.forEach((r) => {
        const dot = el("circle", { cx: X(r.noise_rate), cy: Y(r.estimate), r: 4, fill: c, stroke: css("--surface"), "stroke-width": 2 }, svg);
        const hit = el("circle", { cx: X(r.noise_rate), cy: Y(r.estimate), r: 12, fill: "transparent" }, svg);
        hit.addEventListener("mouseenter", () => {
          const s = svg.getBoundingClientRect().width / W;
          tip.show(`<b>${data.methods[meth].label}</b><br>${Math.round(r.noise_rate * 100)}% flipped · AUROC ${f3(r.estimate)}<br><span style="opacity:.75">[${f3(r.ci_low)}, ${f3(r.ci_high)}]</span>`, X(r.noise_rate) * s, Y(r.estimate) * s);
          dot.setAttribute("r", 5.5);
        });
        hit.addEventListener("mouseleave", () => { tip.hide(); dot.setAttribute("r", 4); });
      });
    });
  }

  // ---------------- head pose ----------------
  function headPoseChart(container, data, budget, methods) {
    container.innerHTML = "";
    const rows = data.head_pose.filter((r) => r.budget === budget && methods.includes(r.method));
    if (!rows.length) { container.innerHTML = '<p class="muted small">Not available.</p>'; return; }
    const poses = [...new Set(rows.map((r) => r.head_pose))].sort((a, b) => a - b);
    const W = 720, H = 280, m = { l: 44, r: 10, t: 12, b: 48 };
    const svg = el("svg", { viewBox: `0 0 ${W} ${H}`, role: "img", "aria-label": "AUROC by head pose" }, container);
    const vals = rows.flatMap((r) => [r.ci_low, r.ci_high]);
    let ymin = Math.floor(Math.min(0.5, ...vals) * 10) / 10, ymax = Math.min(1, Math.ceil(Math.max(...vals) * 10) / 10);
    const band = (W - m.l - m.r) / poses.length;
    const Y = (v) => m.t + (1 - (v - ymin) / (ymax - ymin)) * (H - m.t - m.b);
    const g = el("g", { class: "grid" }, svg);
    for (let v = ymin; v <= ymax + 1e-9; v += 0.1) {
      el("line", { x1: m.l, x2: W - m.r, y1: Y(v), y2: Y(v) }, g);
      el("text", { x: m.l - 6, y: Y(v) + 4, "text-anchor": "end" }, svg).textContent = v.toFixed(1);
    }
    el("line", { class: "chance", x1: m.l, x2: W - m.r, y1: Y(0.5), y2: Y(0.5) }, svg);
    const tip = tooltip(container);
    poses.forEach((p, i) => {
      const cx = m.l + band * (i + 0.5);
      const any = rows.find((r) => r.head_pose === p);
      el("text", { x: cx, y: H - m.b + 18, "text-anchor": "middle" }, svg).textContent = `${p > 0 ? "+" : ""}${p}°`;
      el("text", { x: cx, y: H - m.b + 33, "text-anchor": "middle" }, svg).textContent = `n=${any.n_images}, ${any.n_pos} pos.`;
      methods.forEach((meth, j) => {
        const r = rows.find((q) => q.head_pose === p && q.method === meth);
        if (!r) return;
        const x = cx + (j - (methods.length - 1) / 2) * Math.min(18, band / (methods.length + 1));
        const info = data.methods[meth];
        const c = colorOf(meth, info.family);
        el("line", { x1: x, x2: x, y1: Y(r.ci_low), y2: Y(r.ci_high), stroke: c, "stroke-width": 2 }, svg);
        el("circle", { cx: x, cy: Y(r.auroc), r: 4.5, fill: info.kind === "zeroshot" ? css("--surface") : c, stroke: c, "stroke-width": 2 }, svg);
        const hit = el("rect", { x: x - 8, y: Y(r.ci_high) - 4, width: 16, height: Y(r.ci_low) - Y(r.ci_high) + 8, fill: "transparent" }, svg);
        hit.addEventListener("mouseenter", () => {
          const s = svg.getBoundingClientRect().width / W;
          tip.show(`<b>${info.label}</b><br>head pose ${p}° · AUROC ${f3(r.auroc)}<br><span style="opacity:.75">[${f3(r.ci_low)}, ${f3(r.ci_high)}]</span>`, x * s, Y(r.auroc) * s);
        });
        hit.addEventListener("mouseleave", () => tip.hide());
      });
    });
  }

  // ---------------- tables ----------------
  function resultsTable(container, data, methods) {
    const budgets = data.protocol.budgets;
    const au = data.curves.filter((r) => r.metric === "auroc" && r.condition === "clean");
    const ba = data.curves.filter((r) => r.metric === "balanced_accuracy" && r.condition === "clean");
    let h = `<table><caption class="sr-only">AUROC by method and label budget</caption><thead><tr><th>Method</th>${budgets.map((b) => `<th class="num">k=${budgetLabel(b)}</th>`).join("")}</tr></thead><tbody>`;
    methods.forEach((m) => {
      const info = data.methods[m];
      const sw = `<span class="swatch" style="background:${colorOf(m, info.family)}"></span>`;
      if (info.kind === "zeroshot") {
        const r = au.find((q) => q.method === m);
        h += `<tr><td>${sw}${info.label}</td><td class="num" colspan="${budgets.length}" style="text-align:center">${f3(r && r.estimate)} <span class="muted">(no labels)</span></td></tr>`;
        return;
      }
      h += `<tr><td>${sw}${info.label}</td>${budgets.map((b) => {
        const r = au.find((q) => q.method === m && q.budget === b);
        const s = ba.find((q) => q.method === m && q.budget === b);
        return `<td class="num" title="95% CI [${f3(r && r.ci_low)}, ${f3(r && r.ci_high)}]; balanced accuracy ${f3(s && s.estimate)}">${f3(r && r.estimate)}</td>`;
      }).join("")}</tr>`;
    });
    container.innerHTML = h + "</tbody></table>";
  }

  function pairedTable(container, data) {
    if (!data.paired.length) { container.innerHTML = ""; return; }
    let h = `<table><thead><tr><th>Comparison</th><th class="num">k</th><th class="num">ΔAUROC</th><th class="num">95% CI</th><th class="num">beyond subject noise?</th></tr></thead><tbody>`;
    data.paired.forEach((r) => {
      h += `<tr><td>${data.methods[r.method_a].label.split(" (")[0]} − ${data.methods[r.method_b].label.split(" (")[0]}</td><td class="num">${budgetLabel(r.budget)}</td><td class="num">${r.delta_auroc > 0 ? "+" : ""}${f3(r.delta_auroc)}</td><td class="num">[${f3(r.ci_low)}, ${f3(r.ci_high)}]</td><td class="num">${r.excludes_zero ? (Math.min(Math.abs(r.ci_low), Math.abs(r.ci_high)) < 0.0015 ? "borderline" : "yes") : "no"}</td></tr>`;
    });
    container.innerHTML = h + "</tbody></table>";
  }

  function heatmaps(container, data) {
    container.innerHTML = "";
    const rates = data.error_rates || [];
    const methods = [...new Set(rates.map((r) => r.method))].filter((m) => data.methods[m] && data.methods[m].primary);
    if (!methods.length) { container.innerHTML = '<p class="muted small">Not available.</p>'; return; }
    const V = [10, 0, -10], H = [-15, -10, -5, 0, 5, 10, 15];
    const lo = css("--seq-1"), hi = css("--seq-9");
    const mix = (a, b, t) => { const p = (h) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16)); const A = p(a), B = p(b); return `rgb(${A.map((x, i) => Math.round(x + (B[i] - x) * t)).join(",")})`; };
    methods.forEach((m) => {
      const d = document.createElement("div"); d.className = "heat";
      let h = `<h4>${data.methods[m].label}</h4><table><thead><tr><th></th>${H.map((x) => `<th>${x}°</th>`).join("")}</tr></thead><tbody>`;
      V.forEach((v) => {
        h += `<tr><th>${v}°</th>`;
        H.forEach((hh) => {
          const cell = rates.filter((r) => r.method === m && r.gaze_v === v && r.gaze_h === hh);
          const n = cell.reduce((s, r) => s + r.n, 0);
          const rate = n ? cell.reduce((s, r) => s + r.predicted_positive_rate * r.n, 0) / n : null;
          const bg = rate == null ? "transparent" : mix(lo, hi, rate);
          const fg = rate != null && rate > 0.55 ? "#fff" : "var(--ink)";
          const ring = v === 0 && hh === 0 ? "outline:2px solid var(--accent);outline-offset:-2px;" : "";
          h += `<td style="background:${bg};color:${fg};${ring}" title="V=${v}°, H=${hh}°: ${rate == null ? "–" : (rate * 100).toFixed(0) + "%"} predicted camera-directed (n=${n})">${rate == null ? "–" : (rate * 100).toFixed(0)}</td>`;
        });
        h += "</tr>";
      });
      d.innerHTML = h + "</tbody></table>";
      container.appendChild(d);
    });
  }

  function protocolViz(data) {
    const foldsEl = document.getElementById("fold-viz");
    if (!foldsEl || !data.folds) return;
    foldsEl.innerHTML = "";
    const subjects = data.folds.flatMap((f) => f.test_subjects).sort();
    data.folds.forEach((f) => {
      const row = document.createElement("div"); row.className = "fold-row";
      const test = new Set(f.test_subjects);
      row.innerHTML = `<span>fold ${f.fold + 1}</span><span class="dots">${subjects.map((s) => `<i class="dot ${test.has(s) ? "test" : ""}" title="subject ${s}${test.has(s) ? " (test)" : ""}"></i>`).join("")}</span>`;
      foldsEl.appendChild(row);
    });
    const bars = document.getElementById("budget-viz");
    if (bars) {
      const b = data.protocol.budgets.filter((x) => x !== "all").map(Number);
      const allRow = data.curves.find((r) => r.budget === "all" && r.metric === "auroc");
      const allN = allRow ? allRow.mean_n_train / 2 : Math.max(...b) * 10; // mean examples per class at ALL
      const h = (k) => Math.max(4, (Math.log(k) / Math.log(allN)) * 100);
      bars.innerHTML = b.map((k) => `<div class="bar" style="height:${h(k)}%" title="${k} per class"><span>${k}</span></div>`).join("") +
        `<div class="bar" style="height:100%;background:var(--ink-3)" title="ALL: about ${Math.round(allN)} per class on average (imbalanced)"><span>ALL</span></div>`;
    }
  }

  // Findings: the wording is fixed, every number is looked up in results.json.
  function findings(data) {
    const ol = document.getElementById("findings");
    if (!ol) return;
    const get = (m, b, metric = "auroc", cond = "clean", rate = 0) =>
      data.curves.find((r) => r.method === m && r.budget === b && r.metric === metric && r.condition === cond && Math.abs(r.noise_rate - rate) < 1e-9);
    const ci = (r) => (r ? `${f3(r.estimate)} <span class="muted">[${f3(r.ci_low)}, ${f3(r.ci_high)}]</span>` : "–");
    const items = [];
    const g5 = get("geometry", "5"), g100 = get("geometry", "100"), gall = get("geometry", "all");
    if (g5 && gall) items.push(`<strong>Nine geometric features were the most label-efficient representation at every budget.</strong> AUROC was ${ci(g5)} at 5 labels per class, ${ci(g100)} at 100, and ${ci(gall)} with all training data.`);
    const dv = data.curves.filter((r) => r.method === "dinov2" && r.metric === "auroc" && r.condition === "clean").map((r) => r.estimate);
    if (dv.length) items.push(`<strong>A linear probe on frozen DINOv2 stayed at chance</strong> (${f3(Math.min(...dv))}–${f3(Math.max(...dv))}) even with all training images. Its embeddings encode head pose rather than gaze (post-hoc diagnostic in the paper).`);
    const lz = get("l2cs_zeroshot", "0"), lall = get("l2cs", "all");
    if (lz && lall) items.push(`<strong>The pretrained gaze estimator mainly helped without labels.</strong> L2CS-Net's angle-to-camera score reached ${ci(lz)} with zero FewGaze labels. A head trained on its angles reached ${f3(lall.estimate)} with all training data.`);
    const cz = get("clip_zeroshot", "0");
    if (cz) items.push(`<strong>CLIP zero-shot prompts were weak</strong> at ${ci(cz)}, close to chance for this fine-grained distinction.`);
    ol.innerHTML = items.map((t) => `<li>${t}</li>`).join("");
  }

  function fill(data) {
    document.querySelectorAll("[data-fill]").forEach((e) => {
      const path = e.getAttribute("data-fill").split(".");
      let v = data; for (const p of path) v = v == null ? v : v[p];
      if (v != null) e.textContent = typeof v === "number" ? v.toLocaleString("en-US") : v;
    });
  }

  let state = { metric: "auroc", pose: null };
  function renderAll(data) {
    const primary = Object.keys(data.methods).filter((m) => data.methods[m].primary);
    const ablation = Object.keys(data.methods).filter((m) => !data.methods[m].primary && data.methods[m].kind === "trained");
    learningCurve(document.getElementById("lc"), data, state.metric, primary.filter((m) => state.metric === "auroc" || data.methods[m].kind === "trained" || m === "clip_zeroshot"));
    legend(document.getElementById("lc-legend"), data, primary);
    const trainedPrimary = primary.filter((m) => data.methods[m].kind === "trained");
    learningCurve(document.getElementById("lc-ablation"), data, "auroc", trainedPrimary.concat(ablation));
    legend(document.getElementById("lc-ablation-legend"), data, trainedPrimary.concat(ablation));
    const nb = [...new Set(data.curves.filter((r) => r.condition === "noise").map((r) => r.budget))].sort((a, b) => a - b);
    const nz = document.getElementById("noise");
    nz.innerHTML = "";
    nb.forEach((b) => { const d = document.createElement("div"); d.className = "chart"; nz.appendChild(d); noiseChart(d, data, b, trainedPrimary); });
    legend(document.getElementById("noise-legend"), data, trainedPrimary);
    const poses = [...new Set(data.head_pose.map((r) => r.budget))];
    state.pose = state.pose || poses[0];
    headPoseChart(document.getElementById("pose"), data, state.pose, primary);
    legend(document.getElementById("pose-legend"), data, primary);
    resultsTable(document.getElementById("results-table"), data, primary.concat(ablation));
    pairedTable(document.getElementById("paired-table"), data);
    heatmaps(document.getElementById("heatmaps"), data);
    protocolViz(data);
  }

  function wire(data) {
    document.querySelectorAll("[data-metric]").forEach((b) => b.addEventListener("click", () => {
      state.metric = b.getAttribute("data-metric");
      document.querySelectorAll("[data-metric]").forEach((x) => x.setAttribute("aria-pressed", x === b ? "true" : "false"));
      renderAll(data);
    }));
    document.querySelectorAll("[data-pose]").forEach((b) => b.addEventListener("click", () => {
      state.pose = b.getAttribute("data-pose");
      document.querySelectorAll("[data-pose]").forEach((x) => x.setAttribute("aria-pressed", x === b ? "true" : "false"));
      renderAll(data);
    }));
    let t; addEventListener("resize", () => { clearTimeout(t); t = setTimeout(() => renderAll(data), 150); });
  }

  fetch("data/results.json", { cache: "no-cache" })
    .then((r) => { if (!r.ok) throw new Error(r.status); return r.json(); })
    .then((data) => {
      window.__fewgazeData = data;
      document.querySelectorAll("[data-needs-results]").forEach((e) => (e.hidden = false));
      document.querySelectorAll("[data-no-results]").forEach((e) => (e.hidden = true));
      fill(data); findings(data); wire(data); renderAll(data);
    })
    .catch(() => {
      document.querySelectorAll("[data-needs-results]").forEach((e) => (e.hidden = true));
      document.querySelectorAll("[data-no-results]").forEach((e) => (e.hidden = false));
    });
})();
